# EventBridge scheduled rule -- Terraform
resource "aws_cloudwatch_event_rule" "daily_pipeline" {
  name                = "daily-orders-pipeline-trigger"
  schedule_expression = "cron(0 6 * * ? *)"
}

resource "aws_cloudwatch_event_target" "start_step_function" {
  rule     = aws_cloudwatch_event_rule.daily_pipeline.name
  arn      = aws_sfn_state_machine.pipeline.arn
  role_arn = aws_iam_role.eventbridge_invoke_sfn.arn
}

# Step Functions state machine -- Amazon States Language (JSON)
{
  "Comment": "Daily 50-source ingestion pipeline",
  "StartAt": "FetchAllSources",
  "States": {
    "FetchAllSources": {
      "Type": "Map",
      "ItemsPath": "$.sources",
      "MaxConcurrency": 10,
      "Iterator": {
        "StartAt": "FetchSource",
        "States": {
          "FetchSource": {
            "Type": "Task",
            "Resource": "arn:aws:lambda:us-east-1:123456789:function:fetch-source",
            "Retry": [{ "ErrorEquals": ["States.TaskFailed"],
                        "IntervalSeconds": 30, "MaxAttempts": 3, "BackoffRate": 2.0 }],
            "Catch": [{ "ErrorEquals": ["States.ALL"],
                        "ResultPath": "$.error", "Next": "LogFailedSource" }],
            "End": true
          },
          "LogFailedSource": {
            "Type": "Task",
            "Resource": "arn:aws:lambda:us-east-1:123456789:function:log-dead-letter",
            "End": true
          }
        }
      },
      "Next": "RunSparkValidation"
    },
    "RunSparkValidation": {
      "Type": "Task",
      "Resource": "arn:aws:states:::elasticmapreduce:addStep.sync",
      "Parameters": {
        "ClusterId.$": "$.clusterId",
        "Step": { "Name": "ValidateAndTransform", "ActionOnFailure": "CONTINUE",
                  "HadoopJarStep": { "Jar": "command-runner.jar",
                    "Args": ["spark-submit", "s3://bucket/scripts/validate.py"] } }
      },
      "Next": "NotifyComplete"
    },
    "NotifyComplete": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789:function:notify-slack",
      "End": true
    }
  }
}
